/**
 * Gymify RPG — Design System & Asset Vault (v0 Harvested)
 *
 * All SVGs extracted directly from https://gymify-phi.vercel.app/
 * Includes:
 * - 7 Core Stat Glyphs (STR, END, AGI, DEX, CON, WIS, SPR)
 * - 7 Adventurer Rank Crests (Copper -> Mythic)
 * - 8 Modality Badges
 * - 4 Illustrated Loot Chests (Common -> Mythic)
 * - HUD Elements (Stat Radar, Rest Timer Ring, Gathering Ring, Corner Filigree)
 * - Talent Tree Constellation Star Map
 */

export function svgToDataUri(svgString: string): string {
  // Safe cross-platform base64 encoding
  try {
    const g = globalThis as { Buffer?: { from: (s: string) => { toString: (enc: string) => string } } };
    if (typeof g.Buffer !== 'undefined') {
      return 'data:image/svg+xml;base64,' + g.Buffer.from(svgString).toString('base64');
    }
    if (typeof btoa !== 'undefined') {
      return 'data:image/svg+xml;base64,' + btoa(unescape(encodeURIComponent(svgString)));
    }
  } catch {}
  return `data:image/svg+xml;utf8,${encodeURIComponent(svgString)}`;
}

